import java.math.BigDecimal;
import java.math.RoundingMode;

static BigDecimal convertReais(String text) {
    BigDecimal value = new BigDecimal(text.strip()); // contract: 123.45
    if (value.signum() <= 0) {
        throw new IllegalArgumentException("The value must ser positivo.");
    }
    return value.setScale(2, RoundingMode.HALF_EVEN);
}

// Problem: "given an array, count how many numbers are positive"
//
// Decomposition in Portuguese BEFORE the code:
// 1. start a counter at zero
// 2. cycle through each number
// 3. increase the counter when the number is greater than zero
// 4. return the counter
//
// JUST NOW translate to Java:
int countPositive(int[] numbers) {
    int quantity = 0;
    for (int number : numbers) {
        if (number > 0) quantity++;
    }
    return quantity;
}

int factorial(int n) {
    int result = 1;
    for (int i = 1; i <= n; i++) {
        result = result * i;
    }
    return result;
}
// dry run manual of factorial(4):
// i=1: result = 1*1 = 1
// i=2: result = 1*2 = 2
// i=3: result = 2*3 = 6
// i=4: result = 6*4 = 24
// i=5: condition "i<=4" false, exits the loop
// returns 24

