static void doubleNumber(int n) {
    n = n * 2; // only changes the local copy
}

static void renomeia(Coffee c) {
    c.type = "renomeado"; // changes the OBJECT pointed to (visible outside!)
}

static void trocaObject(Coffee c) {
    c = new Coffee(); // only swaps what the LOCAL copy of the reference points to
}

