myCoffee.type = "original";
renomeia(myCoffee);
System.out.println(myCoffee.type); // "renamed" -- the object on the heap has changed

trocaObject(myCoffee);
System.out.println(myCoffee.type); // still "renamed" -- reassigning the local parameter does not affect the external variable

