// T needs to be some type that implements Comparable<T>
public static <T extends Comparable<T>> T greater(List<T> list) {
    T greater = list.get(0);
    for (T item : list) {
        if (item.compareTo(greater) > 0) greater = item;
    }
    return greater;
}

// ? extends Number: accepts lists of Number OR ANY SUBTYPE -- safe read only
static double sumAll(List<? extends Number> numbers) {
