public record Cash(BigDecimal value, Currency currency) {
    public Cash {
        Objects.requireNonNull(value);
        Objects.requireNonNull(currency);
        if (value.signum() < 0) throw new IllegalArgumentException("value negative");
        value = value.setScale(currency.getDefaultFractionDigits(), RoundingMode.HALF_EVEN);
    }
}

sealed interface Payment permits Pix, Card, BankSlip {}
record Pix(String key) implements Payment {}
record Card(String token, int installments) implements Payment {}
record BankSlip(LocalDate dueDate) implements Payment {}

static String description(Payment payment) {
    return switch (payment) {
        case Pix(String key) -> "PIX " + key;
        case Card(var token, var installments) -> installments + "x";
        case BankSlip(LocalDate dueDate) -> "vence in " + dueDate;
    };
}

