int factorial(int n) {
    if (n <= 1) return 1;              // BASE CASE -- without this, infinite recursion
    return n * factorial(n - 1);         // RECURSIVE CASE -- minor problem + call itself
}
// factorial(4) = 4 * factorial(3)
// = 4 * (3 * factorial(2))
// = 4 * (3 * (2 * factorial(1)))
//             = 4 * (3 * (2 * 1))
//             = 24

// iterative version of the same factorial (chapter 79, loop reasoning):
int factorialIterativo(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) result *= i;
    return result;
}
// same result, WITHOUT the cost of stacking N frames on the stack

// ❌ naive -- O(2ⁿ), recalculates the same values ​​repeatedly:
int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}

// ✅ with memoization -- O(n), saves already calculated results:
Map<Integer, Long> cache = new HashMap<>();
long fibonacciMemo(int n) {
    if (n <= 1) return n;
    if (cache.containsKey(n)) return cache.get(n); // already calculated, do not redo
    long result = fibonacciMemo(n - 1) + fibonacciMemo(n - 2);
    cache.put(n, result);
    return result;
}

int searchBinaria(int[] sorted, int alvo) {
    int start = 0, end = sorted.length - 1;
    while (start <= end) {
        int middle = start + (end - start) / 2; // avoid overflow of (start+end)/2 in giant arrays
        if (sorted[middle] == alvo) return middle;
        else if (sorted[middle] < alvo) start = middle + 1; // discard left half
        else end = middle - 1;                            // discard right half
    }
    return -1; // not found
}
// O(log n) -- ONLY works if the array is already ORDERED

int[] mergeSort(int[] array) {
    if (array.length <= 1) return array; // base case -- 0 or 1 element is already "sorted"

    int middle = array.length / 2;
    int[] left = mergeSort(Arrays.copyOfRange(array, 0, middle));
    int[] right = mergeSort(Arrays.copyOfRange(array, middle, array.length));

    return merge(left, right); // combines the two already ordered
}

int[] merge(int[] left, int[] right) {
    int[] result = new int[left.length + right.length];
    int i = 0, j = 0, k = 0;
    while (i < left.length && j < right.length) {
        result[k++] = (left[i] <= right[j]) ? left[i++] : right[j++];
    }
    while (i < left.length) result[k++] = left[i++];
    while (j < right.length) result[k++] = right[j++];
    return result;
}

static Set<String> bfs(Map<String, List<String>> graph, String source) {
    Set<String> visited = new LinkedHashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.add(source);
    while (!queue.isEmpty()) {
        String current = queue.removeFirst();
        if (!visited.add(current)) continue;
        graph.getOrDefault(current, List.of()).stream()
            .filter(neighbor -> !visited.contains(neighbor))
            .forEach(queue::addLast);
    }
    return visited;
}

