@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ItemUnavailableException.class) // your exception from chapter 17!
    public ResponseEntity<ErrorDTO> handleItemUnavailable(ItemUnavailableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT) // 409
            .body(new ErrorDTO("ITEM_UNAVAILABLE", e.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class) // triggered by @Valid when failure
    public ResponseEntity<ErrorDTO> handleValidation(MethodArgumentNotValidException e) {
        String messages = e.getBindingResult().getFieldErrors().stream()
            .map(error -> error.getField() + ": " + error.getDefaultMessage())
            .collect(Collectors.joining("; ")); // streams, chapter 13
        return ResponseEntity.badRequest() // 400
            .body(new ErrorDTO("VALIDATION", messages));
    }

    @ExceptionHandler(Exception.class) // safety net -- NEVER let stack trace leak
    public ResponseEntity<ErrorDTO> handleErrorGeneric(Exception e) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR) // 500
            .body(new ErrorDTO("ERROR_INTERNO", "Something deu wrong. Tente novamente."));
    }
}

