@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // disabled for stateless APIs with JWT (explained below)
            .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)) // no session!
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/auth/login", "/auth/register").permitAll() // public
                .requestMatchers(HttpMethod.GET, "/books/**").permitAll() // public reading
                .requestMatchers("/admin/**").hasRole("ADMIN")       // only admin
                .anyRequest().authenticated()                       // remainder exige login
            )
            .addFilterBefore(jwtAuthFilter(), UsernamePasswordAuthenticationFilter.class) // its filtro JWT customizado
            .build();
    }
}

@Service
public class JwtService {
    private final String keySecret = "..."; // NEVER really hardcoded -- comes from environment variable (chapter 27!)

    public String generateToken(User user) {
        return Jwts.builder()
            .subject(user.getEmail())
            .claim("role", user.getRole())
            .issuedAt(new Date())
            .expiration(new Date(System.currentTimeMillis() + 3600_000)) // 1 hour
            .signWith(keyAsBytes())
            .compact();
    }

    public boolean validate(String token) {
        try {
            Jwts.parser().verifyWith(keyAsBytes()).build().parseSignedClaims(token);
            return true;
        } catch (JwtException e) { // expired, invalid signature, malformed...
            return false;
        }
    }
}

