@Aspect
@Component
public class ExecutionLogAspect {

    private static final Logger log = LoggerFactory.getLogger(ExecutionLogAspect.class);

    // "pointcut": WHICH methods to intercept -- every method in any class in the service package
    @Around("execution(* with.felipy.library.service..*(..))")
    public Object measureTempo(ProceedingJoinPoint joinPoint) throws Throwable {
        long start = System.nanoTime();
        Object result = joinPoint.proceed(); // call the REAL method -- exactly like method.invoke() from chapter 20
        long durationMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        log.info("{} executou in {}ms", joinPoint.getSignature(), durationMs);
        return result;
    }
}

