public class Counter {
    private int value = 0;
    public void increment() { value++; } // NOT atomic! is read + add + write
    public int getValue() { return value; }
}

// two threads calling increment() 100_000 times each, at the same time,
// often does NOT result in 200_000 -- because "value++" is not a
// single operation: threads can read the same value before one of them writes.

public class Counter {
    private int value = 0;
    public synchronized void increment() { value++; } // only one thread at a time executes this
    public synchronized int getValue() { return value; }
}

// or a synchronized block over a specific object -- more granular:
private final Object trava = new Object();
void operationCritical() {
    synchronized (trava) {
        // only one thread at a time enters here
    }
}

// AtomicInteger: atomic increment without needing manual synchronized
import java.util.concurrent.atomic.AtomicInteger;
AtomicInteger counter = new AtomicInteger(0);
counter.incrementAndGet(); // truly thread safe

// ExecutorService: a managed thread pool, instead of loose "new Thread()"
import java.util.concurrent.*;
ExecutorService pool = Executors.newFixedThreadPool(4);
Future<Integer> result = pool.submit(() -> {
    return 2 + 2; // task that returns a value
});
System.out.println(result.get()); // block until the result is ready
pool.shutdown(); // always close the pool when you no longer need it

