public class Flag {
    private boolean ready = false; // WITHOUT volatile

    void markReady() { ready = true; }   // Thread A calls this
    void esperar() {
        while (!ready) { }                // Thread B gets stuck HERE FOREVER,
                                            // even after marking ready=true --
                                            // because B might be reading a value
                                            // old "curly", never updated
                                            // from main memory
    }
}

private volatile boolean ready = false;
// a volatile write happens-before a later read
// of the same variable: this provides visibility and ordering restrictions.
// Does not mean "bypass cache" literally and does not make value++ atomic.

Object resourceA = new Object();
Object resourceB = new Object();

// Thread 1:
synchronized (resourceA) {
    // ...do something...
    synchronized (resourceB) { // hope to be able to stop B
        // ...
    }
}

// Thread 2 (running AT THE SAME TIME):
synchronized (resourceB) {
    // ...do something...
    synchronized (resourceA) { // hope to be able to stop A
        // ...
    }
}
// if Thread 1 gets resourceA and Thread 2 gets resourceB ALMOST at the same time
// time, Thread 1 waits for resourceB (which Thread 2 has), and
// Thread 2 waits for resourceA (which Thread 1 has) -- DEADLOCK,
// both are blocked FOREVER

CompletableFuture<Book> future = CompletableFuture
    .supplyAsync(() -> findBookInBank(id))       // runs in another thread, does not block here
    .thenApply(book -> enrichWithDataExternal(book)) // chain -- run WHEN the previous one finishes
    .thenApply(BookDTO::from);                       // one more chained step

future.thenAccept(dto -> System.out.println("Ready: " + dto));
// the code HERE continues running IMMEDIATELY, without waiting
// the "future" finish -- typical of asynchronous/reactive programming

// combining TWO independent asynchronous operations:
CompletableFuture<Book> searchBook = CompletableFuture.supplyAsync(() -> findBook(id));
CompletableFuture<Author> searchAuthor = CompletableFuture.supplyAsync(() -> findAuthor(authorId));

CompletableFuture<String> combinado = searchBook.thenCombine(searchAuthor,
    (book, author) -> book.getTitle() + " by " + author.getName());
// the two searches run IN PARALLEL, and "combined" only resolves when
// BOTH finish -- much faster than searching for one, waiting, then
// fetch the other sequentially

