public class Order { // Aggregate Root
    private Long id;
    private List<ItemOrder> items; // part of the aggregate, NEVER accessed directly from outside
    private StatusOrder status;

    // every change goes through a Request method -- never "order.getItems().add(...)" directly from outside
    public void addItem(Product product, int quantity) {
        if (status != StatusOrder.ABERTO) {
            throw new OrderClosedException(); // the business rule LIVES here, not spread
        }
        items.add(new ItemOrder(product, quantity));
    }
}

